userStyle.value:
@import url("im_design_system/v1.0.0/css/common.css");

/* override common.css */
.field.im-common-button-area .button {
  min-width: 6.5em;
}
@media screen and (max-width: 320px) {
  .field.im-common-button-area .button {
    min-width: 4.5em;
  }
}

@media screen and (max-width: 480px) {
  .work-time {
    width: 18rem;
  }
}

@media screen and (max-width: 1023px) {
  .content-area {
    padding-top: 0 !important;
    height: auto !important;
  }
}

.form-area {
  border-radius: 4px;
}

.tabs li.is-active a {
  font-weight: bold;
  border-bottom-width: 3px;
}

/* card */
.holiday-user-card {
  background: #ccc;
  border-radius: 4px;
}

.holiday-user-card:hover {
  filter: saturate(125%);
  box-shadow: 0 0.2rem 0.2rem 0 rgb(0, 0, 0, 14%), 0 0.3rem 0.1rem -0.2rem rgb(0, 0, 0, 20%), 0 0.1rem 0.5rem 0 rgb(0, 0, 0, 12%);
}

.holiday-name-area {
  display: flex;
  justify-content: flex-end;
}

.holiday-name {
  border-radius: 2px;
  overflow-wrap: break-word;
  color: #ccc;
}

.holiday-user-card .holiday-user-id {
  opacity: 0.85;
  overflow-wrap: anywhere;
}

.holiday-user-card-list table {
  table-layout: fixed;
}

.holiday-user-card-list td {
  border: none;
}

/* padding reset */
.im-hichee-container.im-hichee-production-mode .holiday-user-card div {
  padding: 0;
}

/* for designer mode */
.im-hichee-container.im-hichee-designer-mode .holiday-user-card-list {
  min-width: 500px;
}

/* responsive & sticky */
.contents-area > div {
  position: relative;
  overflow: auto;
}

.sticky-area {
  position: sticky !important;
  top: 0;
  z-index: 1;
}

.holiday-user-card-list thead {
  position: sticky !important;
  top: 3rem;
  z-index: 1;
}

.contents-area {
  height: calc(100% - 7.8rem);
}

.holiday-user-card-list {
  width: calc(100% / 7);
}

.im-hichee-container.im-hichee-production-mode .holiday-list-header {
  display: none;
  border-bottom: 2px solid #dbdbdb;
}

@media screen and (max-width: 768px) {
  .holiday-user-card-list {
    width: 50%;
  }
}

@media screen and (min-width: 769px) and (max-width: 1023px) {
  .holiday-user-card-list {
    width: calc(100% / 3);
  }
}

@media screen and (min-width: 1024px) and (max-width: 1216px) {
  .holiday-user-card-list {
    width: 25%;
  }
}

@media screen and (max-width: 1216px) {
  .im-hichee-container.im-hichee-production-mode .holiday-table-header {
    display: none;
  }

  .im-hichee-container.im-hichee-production-mode .holiday-list-header {
    display: flex;
  }

  .contents-area.px-3 {
    padding-right: 0 !important;
    padding-left: 0 !important;
  }
}

/* filter */
.filter-checkbox label {
  display: inline-flex;
  padding: 0.5em 0.75em;
  border-radius: 4px;
}

.filter-checkbox label:hover {
  background: #f5f5f5;
}

.filter-checkbox input[type="checkbox"] {
  width: 1.2em;
  height: 1.2em;
}

.summary-area {
  display: inline-flex !important;
}

/* override common.css */
.im-common-table-area {
  height: calc(100% - 7.8rem);
}

.user-table thead {
  position: sticky;
  z-index: 1;
  top: 0;
  left: 0;
}

/* refer */
.refer-field {
  border-bottom: 1px solid #eee;
  margin-bottom: 0.5em;
  min-width: 6em;
  max-width: 100%;
  padding-bottom: calc(0.5em - 1px);
  overflow-wrap: break-word;
}

.textarea[readonly] {
  border-color: #dbdbdb;
  box-shadow: none;
}

.withdraw-holiday {
  border-radius: 4px;
}

.confirmation-message {
  border-radius: 2px;
}

.show-withdraw-reason {
  display: inline-flex !important;
  justify-content: center;
  align-items: center;
  justify-items: center;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  cursor: pointer;
}

.show-withdraw-reason:hover {
  filter: brightness(115%);
  cursor: pointer;
}

/* dialog */
@media screen and (max-width: 500px) {
  .dialog-content {
    min-width: 0 !important;
    width: 85vw !important;
  }
}

@media screen and (max-height: 685px) {
  .dialog-content {
    min-height: 0 !important;
    height: 90vh !important;
  }
}

